 "content": "def transform(grid):
    """Repeat the only patterned panel across panels separated by full 4-lines."""
    h, w = len(grid), len(grid[0])
    sep = 4
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == sep for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == sep for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))

    # Locate the panel containing the non-background pattern. The most
    # frequent non-separator color in the input is the panel background.
    counts = {}
    for row in grid:
        for v in row:
            if v != sep:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    source = None
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            if any(v not in (sep, bg) for row in panel for v in row):
                source = panel
                break
        if source is not None:
            break
    if source is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    sh, sw = len(source), len(source[0])
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            if r1-r0 == sh and c1-c0 == sw:
                for dr in range(sh):
                    out[r0+dr][c0:c0+sw] = source[dr][:]
    return out
